otal_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 60 THEN \'31-60\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 90 THEN \'61-90\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 180 THEN \'91-180\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 360 THEN \'181-360\' ELSE \'>360\' END AS aging_interval FROM WeightedAging ORDER BY branch_code, sku_group,BRANCH_NAME ), meta as (Select * from (SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data)where rn=1) select a.*, b.CATEGORY from age a left join meta b on LOWER(a.sku_group)=LOWER(b.sku_group); Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging_shivera as select * from snitch_db.maplemonk.Offline_Inventory_aging where BRANCH_CODE IN (\'17\', \'38\', \'28\', \'36\', \'24\', \'26\', \'23\', \'40\', \'37\', \'21\', \'12\', \'15\', \'4\', \'31\', \'18\', \'7\', \'39\', \'5\', \'22\', \'42\', \'64\',\'65\',\'66\',\'68\') ; create or replace table snitch_db.maplemonk.offline_metrics_shivera as select * from snitch_db.maplemonk.offline_metrics where lower(PARTNER) IN (\'shivera lifestyle\') ; create or replace table snitch_db.maplemonk.offline_master_shivera as select * from snitch_db.maplemonk.offline_master where lower(PARTNER) IN (\'shivera lifestyle\'); create or replace table snitch_db.maplemonk.offline_metrics_chennai as select * from snitch_db.maplemonk.offline_metrics where lower(branch_code) IN (\'53\',\'84\') ; create or replace table snitch_db.maplemonk.offline_master_chennai as select * from snitch_db.maplemonk.offline_master where branch_code IN (\'53\',\'84\'); CREATE or replace TABLE snitch_db.maplemonk.Offline_Detailed_Summary_R2R AS SELECT A.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner, B.\"Rent \" ::INT AS RENT, B.\"Size \"::INT AS SIZE FROM snitch_db.maplemonk.Offline_Detailed_Summary AS A LEFT JOIN snitch_db.maplemonk.offline_store_details AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" WHERE A.marketplace_mapped NOT LIKE \'%- WH -%\' AND B.\"Rent \" =B.\"Rent \" ::INT ;",
